/// A `FederationDirectory` that delegates to `inner`, except where a method
/// has been declared faulted — there it returns [`Error::Unsupported`].
///
/// Cloneable and `Send + Sync`, so it drops into any fixture that takes a
/// directory. The fault set is by METHOD NAME, matching the `method` field
/// `Error::Unsupported` already carries, so a refusal names the same thing the
/// fixture declared.
#[derive(Clone)]
pub struct FaultInjectingDirectory {
    inner: Arc<dyn FederationDirectory>,
    unsupported: BTreeSet<&'static str>,
}

impl std::fmt::Debug for FaultInjectingDirectory {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("FaultInjectingDirectory")
            .field("unsupported", &self.unsupported)
            .finish_non_exhaustive()
    }
}

impl FaultInjectingDirectory {
    /// Wrap a real directory. With no faults declared it is behaviourally
    /// identical to `inner` — a fixture opts INTO each divergence.
    #[must_use]
    pub fn new(inner: Arc<dyn FederationDirectory>) -> Self {
        Self {
            inner,
            unsupported: BTreeSet::new(),
        }
    }

    /// Declare that `method` answers `Error::Unsupported { method }`.
    ///
    /// The name is NOT validated against the trait: an unknown name is inert
    /// rather than an error, because a fixture written against a newer persist
    /// should degrade to *"that fault did not fire"* and fail on its own
    /// assertion, not panic inside the double. Use [`Self::faults`] to assert
    /// what was actually declared.
    #[must_use]
    pub fn unsupported(mut self, method: &'static str) -> Self {
        self.unsupported.insert(method);
        self
    }

    /// The declared fault set — so a fixture can assert its own setup.
    #[must_use]
    pub fn faults(&self) -> &BTreeSet<&'static str> {
        &self.unsupported
    }

    fn faulted(&self, method: &'static str) -> Option<Error> {
        self.unsupported
            .contains(method)
            .then_some(Error::Unsupported { method })
    }
}

